using System.IO;using System.Text.Json;using System.Security.Cryptography;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Core.Services.FreeCanvas;using PixelTart.Modules.AssetLibrary.FreeCanvas;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class CanvasProductClosureWpfTests
{
 [TestMethod]public Task TransparentImportTransformGestureSaveExportAndMissingSource()=>RunSta(async()=>{var root=Environment.GetEnvironmentVariable("KITAO_CANVAS_PRODUCT");if(root is null){Assert.Inconclusive("Explicit output required");return;}EnsureTestApplication();Directory.CreateDirectory(root);var sticker=Path.Combine(root,"sticker.png");var bytes=new byte[32*32*4];for(int y=0;y<32;y++)for(int x=0;x<32;x++){int i=(y*32+x)*4;bytes[i]=20;bytes[i+1]=40;bytes[i+2]=220;bytes[i+3]=(byte)(x>3&&x<28&&y>3&&y<28?128:0);}var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(BitmapSource.Create(32,32,96,96,PixelFormats.Bgra32,null,bytes,128)));using(var f=File.Create(sticker))png.Save(f);var photograph=Path.Combine(root,"photo.jpg");var jpg=new JpegBitmapEncoder();jpg.Frames.Add(BitmapFrame.Create(BitmapSource.Create(24,20,96,96,PixelFormats.Rgb24,null,Enumerable.Repeat((byte)90,24*20*3).ToArray(),72)));using(var f=File.Create(photograph))jpg.Save(f);
 var sourceHash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(sticker)));var editor=new CanvasEditor(new(){PixelWidth=160,PixelHeight=120,Name="透明拼贴"});var store=new CanvasDocumentStore(Path.Combine(root,"canvas-store"));var a=await CanvasPixelRenderer.ImportAsync(sticker,editor.Document,store.DirectoryPath);editor.Add([a with{X=10,Y=8,Width=64,Height=64}]);var first=editor.Selected[0].ObjectId;var b=await CanvasPixelRenderer.ImportAsync(photograph,editor.Document,store.DirectoryPath);editor.Add([b with{X=100,Y=80,Width=30,Height=25}]);editor.Select(first);editor.BeginGesture();editor.Move(10,4);editor.Rotate(20);editor.Resize(70,50);editor.EndGesture();var after=editor.Document;editor.Undo();Assert.AreEqual(10,editor.Document.Objects.Single(o=>o.ObjectId==first).X);editor.Redo();Assert.AreEqual(after.Objects[0].Rotation,editor.Document.Objects[0].Rotation);editor.SetLocked(true);var locked=editor.Document;editor.Move(40,40);editor.Scale(2);Assert.AreSame(locked,editor.Document);editor.SetLocked(false);editor.SetOpacity(.8);editor.StepLayer(true);editor.AddBrushLayer();editor.AddBrushStroke(new([new(.1,.8),new(.6,.8),new(.3,.8)],"#20D060",8,.5,.65));editor.Undo();Assert.AreEqual(0,editor.Document.Objects.Last().BrushStrokes!.Count);editor.Redo();await store.SaveAsync(editor.Document);File.WriteAllText(Path.Combine(root,"CANVAS_ID.txt"),editor.Document.CanvasId.ToString());var output=Path.Combine(root,"canvas-transparent.png");CanvasPixelRenderer.ExportPng(editor.Document,output);using(var f=File.OpenRead(output)){var frame=BitmapDecoder.Create(f,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnLoad).Frames[0];Assert.AreEqual(160,frame.PixelWidth);Assert.AreEqual(120,frame.PixelHeight);Assert.IsTrue(frame.ColorContexts is{Count:1});using(var actualIcc=frame.ColorContexts[0].OpenProfileStream())using(var expectedIcc=new ColorContext(PixelFormats.Bgra32).OpenProfileStream()){using var actualBytes=new MemoryStream();using var expectedBytes=new MemoryStream();actualIcc.CopyTo(actualBytes);expectedIcc.CopyTo(expectedBytes);CollectionAssert.AreEqual(expectedBytes.ToArray(),actualBytes.ToArray());}var rgba=new FormatConvertedBitmap(frame,PixelFormats.Bgra32,null,0);var pixels=new byte[160*120*4];rgba.CopyPixels(pixels,640,0);Assert.AreEqual(0,pixels[3]);foreach(int index in Enumerable.Range(0,160*70).Where(i=>pixels[i*4+3]>10&&pixels[i*4+3]<200)){Assert.AreEqual(220,pixels[index*4+2],12,"No dark/white fringe in unassociated red");Assert.AreEqual(40,pixels[index*4+1],12);Assert.AreEqual(20,pixels[index*4],12);}Assert.IsTrue(Enumerable.Range(0,160*120).Any(i=>pixels[i*4+3] is>0 and<255));File.WriteAllText(Path.Combine(root,"PIXEL_HASH.txt"),Convert.ToHexString(SHA256.HashData(pixels)));}
 var view=new FreeCanvasView(editor,new PixelTart.Modules.AssetLibrary.WpfAssetThumbnailProvider(),store);view.Measure(new Size(960,640));view.Arrange(new Rect(0,0,960,640));view.UpdateLayout();await view.Surface.LoadPreviewsAsync();await Task.Delay(120);await view.Surface.LoadPreviewsAsync();Assert.AreEqual(2,view.Surface.LoadedPreviews.Count,"Imported photo/sticker must be visible, errors="+string.Join(";",view.Surface.SourceErrors.Values));var screenshot=Environment.GetEnvironmentVariable("KITAO_CANVAS_PRODUCT_VISUAL");if(screenshot is not null){Directory.CreateDirectory(screenshot);var picture=new RenderTargetBitmap(960,640,96,96,PixelFormats.Pbgra32);picture.Render(view);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(picture));using var shot=File.Create(Path.Combine(screenshot,"canvas-offscreen.png"));encoder.Save(shot);}var beforeZoom=JsonSerializer.Serialize(editor.Document);view.Surface.SetZoom(.25);view.Surface.SetZoom(2);Assert.AreEqual(beforeZoom,JsonSerializer.Serialize(editor.Document));Assert.IsTrue(await view.FlushAsync());Assert.IsTrue(view.HeaderPanel.Children.OfType<System.Windows.Controls.Button>().Any(b=>Equals(b.Content,"导入")));var librarySource=File.ReadAllText(Path.Combine(TestResources.Root,"src/PixelTart.Modules.AssetLibrary/AssetLibraryPage.cs"));Assert.IsTrue(librarySource.Contains("AssetNewFreeCanvas")&&librarySource.Contains("await NewCanvasAsync()"),"Empty-selection new canvas product route");Assert.IsTrue(view.HeaderPanel.Children.OfType<System.Windows.Controls.Button>().Any(b=>Equals(b.Content,"导出")));Assert.AreEqual(2,editor.Document.SchemaVersion);var uiOutput=Path.Combine(root,"ui-command.png");var beforeCancel=Path.Combine(root,"cancelled.png");using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();Assert.Throws<OperationCanceledException>(()=>CanvasPixelRenderer.ExportPng(editor.Document,beforeCancel,cancelled.Token));Assert.IsFalse(File.Exists(beforeCancel));}view.ExportTransparentTo(uiOutput);CollectionAssert.AreEqual(File.ReadAllBytes(output),File.ReadAllBytes(uiOutput));view.RaiseEvent(new RoutedEventArgs(FrameworkElement.UnloadedEvent));var loaded=await store.LoadAsync(editor.Document.CanvasId);Assert.IsNotNull(loaded);Assert.AreEqual(editor.Document.Objects.Count,loaded.Objects.Count);var copy=editor.Document.Objects.Single(o=>o.ObjectId==first).PlanningSource!.Bind();var owned=RAWSelectionAssistant.Core.Services.Projects.PlanningProjectCopyStorage.Resolve(copy);File.Move(owned,owned+".retained");try{Assert.Throws<FileNotFoundException>(()=>CanvasPixelRenderer.ExportPng(editor.Document,Path.Combine(root,"must-not-export.png")));Assert.IsFalse(File.Exists(Path.Combine(root,"must-not-export.png")));await view.Surface.LoadPreviewsAsync();Assert.IsTrue(view.Surface.SourceErrors.ContainsKey(first),"Missing source publishes recoverable state, no stale bitmap fallback");}finally{File.Move(owned+".retained",owned);await view.Surface.LoadPreviewsAsync();Assert.IsFalse(view.Surface.SourceErrors.ContainsKey(first));}Assert.AreEqual(sourceHash,Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(sticker))));File.WriteAllText(Path.Combine(root,"RESULT.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,width=160,height=120,alpha=true,icc=true,gestureUndo=true,locked=true,ownedSourceHash=true,sourceUnchanged=true,brush=true,scope="WPF real document/store/PNG, not mouse/DPI"}));
 });
 [TestMethod]public Task BrushCoverageDoesNotAccumulateInsideOneStrokeButSeparateStrokesDo()=>RunSta(()=>{EnsureTestApplication();var root=Environment.GetEnvironmentVariable("KITAO_CANVAS_PRODUCT");if(root is null){Assert.Inconclusive("Explicit output required");return Task.CompletedTask;}var editor=new CanvasEditor(new(){PixelWidth=64,PixelHeight=64});editor.AddBrushLayer();editor.AddBrushStroke(new([new(.2,.5),new(.8,.5),new(.2,.5),new(.8,.5)],"#FF0000",16,.5,1));var path=Path.Combine(root,"brush-one.png");CanvasPixelRenderer.ExportPng(editor.Document,path);byte Alpha(string file){using var f=File.OpenRead(file);var bitmap=new FormatConvertedBitmap(BitmapDecoder.Create(f,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnLoad).Frames[0],PixelFormats.Bgra32,null,0);var p=new byte[4];bitmap.CopyPixels(new Int32Rect(32,32,1,1),p,4,0);Assert.AreEqual(255,p[2]);return p[3];}Assert.AreEqual(128,Alpha(path),1,"One stroke max coverage, no repeated alpha at folds");editor.AddBrushStroke(new([new(.2,.5),new(.8,.5)],"#FF0000",16,.5,1));var second=Path.Combine(root,"brush-two.png");CanvasPixelRenderer.ExportPng(editor.Document,second);Assert.AreEqual(192,Alpha(second),1,"Two independent strokes use source-over");return Task.CompletedTask;});
 [TestMethod]public Task IndependentProcessReopenAndExportPixelsMatch()=>RunSta(async()=>{var root=Environment.GetEnvironmentVariable("KITAO_CANVAS_PRODUCT_REOPEN");if(root is null){Assert.Inconclusive("Prior process required");return;}EnsureTestApplication();var store=new CanvasDocumentStore(Path.Combine(root,"canvas-store"));var doc=await store.LoadAsync(Guid.Parse(File.ReadAllText(Path.Combine(root,"CANVAS_ID.txt"))));Assert.IsNotNull(doc);var output=Path.Combine(root,"independent-export.png");CanvasPixelRenderer.ExportPng(doc,output);using var f=File.OpenRead(output);var image=BitmapDecoder.Create(f,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnLoad).Frames[0];var rgba=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var pixels=new byte[image.PixelWidth*image.PixelHeight*4];rgba.CopyPixels(pixels,image.PixelWidth*4,0);Assert.AreEqual(File.ReadAllText(Path.Combine(root,"PIXEL_HASH.txt")),Convert.ToHexString(SHA256.HashData(pixels)));File.WriteAllText(Path.Combine(root,"REOPEN.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,exact=true}));});
}
